-- Fresh dedicated authentication deployment only. Original public session wire is retained.
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.auth_state) THEN RAISE EXCEPTION 'AUTH_AUDIT_INSTALL_NOT_EMPTY';END IF;END $$;
CREATE SCHEMA auth_audit_v4 AUTHORIZATION __OWNER__;
SET ROLE __OWNER__;
CREATE SEQUENCE auth_audit_v4._ddl_epoch;
CREATE TABLE auth_audit_v4._meta(singleton boolean PRIMARY KEY CHECK(singleton),owner_oid oid NOT NULL,app_oid oid NOT NULL,delivery_oid oid NOT NULL,deployment text NOT NULL,epoch bigint NOT NULL,key_check jsonb NOT NULL);
INSERT INTO auth_audit_v4._meta VALUES(true,__OWNER_LITERAL__::regrole::oid,__APP_LITERAL__::regrole::oid,__DELIVERY_LITERAL__::regrole::oid,__DEPLOYMENT__,0,__KEY_CHECK__);
CREATE TABLE auth_audit_v4._ctx(pid integer PRIMARY KEY,tx bigint NOT NULL);
CREATE TABLE auth_audit_v4.streams(scope text NOT NULL,tenant text NOT NULL,emitted bigint NOT NULL DEFAULT 0 CHECK(emitted>=0),emitted_hash text NOT NULL DEFAULT repeat('0',64),delivered bigint NOT NULL DEFAULT 0 CHECK(delivered>=0 AND delivered<=emitted),PRIMARY KEY(scope,tenant));
CREATE TABLE auth_audit_v4.events(id uuid PRIMARY KEY,scope text NOT NULL,tenant text NOT NULL,position bigint NOT NULL CHECK(position>0),lookup_hash text NOT NULL,action text NOT NULL,occurred_ms bigint NOT NULL,previous_hash text NOT NULL,session_ref text NOT NULL,digest text NOT NULL,chain_hash text NOT NULL,sealed jsonb NOT NULL CHECK(jsonb_typeof(sealed)='object' AND octet_length(sealed::text)<=100000),UNIQUE(scope,tenant,position));
CREATE UNIQUE INDEX auth_audit_login_lookup ON auth_audit_v4.events(scope,lookup_hash) WHERE action='AUTH_LOGIN';
CREATE TABLE auth_audit_v4.delivery(id uuid PRIMARY KEY REFERENCES auth_audit_v4.events(id),status text NOT NULL CHECK(status IN('PENDING','RUNNING','RETRY','DELIVERED')),owner uuid,token uuid,fence bigint NOT NULL DEFAULT 0,lease_until timestamptz,available_at timestamptz NOT NULL DEFAULT clock_timestamp(),attempts integer NOT NULL DEFAULT 0,error_code text,receipt jsonb);
CREATE TABLE auth_audit_v4._drafts(pid integer PRIMARY KEY,tx bigint NOT NULL,id uuid NOT NULL,scope text NOT NULL,tenant text NOT NULL,lookup_hash text NOT NULL,action text NOT NULL,position bigint NOT NULL,occurred_ms bigint NOT NULL,previous_hash text NOT NULL,session_ref text,digest text,chain_hash text,sealed jsonb);
CREATE FUNCTION auth_audit_v4._guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='TRUNCATE' OR TG_TABLE_NAME='_meta' OR NOT EXISTS(SELECT 1 FROM auth_audit_v4._ctx WHERE pid=pg_backend_pid() AND tx=txid_current()) OR (TG_TABLE_NAME='events' AND TG_OP<>'INSERT') OR (TG_TABLE_NAME IN('streams','delivery') AND TG_OP='DELETE') THEN RAISE EXCEPTION 'AUTH_AUDIT_DIRECT_WRITE';END IF;
 IF TG_TABLE_NAME='delivery' THEN IF TG_OP='UPDATE' THEN IF OLD.status='DELIVERED' OR OLD.id<>NEW.id THEN RAISE EXCEPTION 'AUTH_AUDIT_DELIVERY_IMMUTABLE';END IF;END IF;END IF;
 IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;END $$;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['_meta','streams','events','delivery','_drafts'] LOOP
 EXECUTE format('CREATE TRIGGER auth_audit_write_guard BEFORE INSERT OR UPDATE OR DELETE ON auth_audit_v4.%I FOR EACH ROW EXECUTE FUNCTION auth_audit_v4._guard()',t);
 EXECUTE format('CREATE TRIGGER auth_audit_truncate_guard BEFORE TRUNCATE ON auth_audit_v4.%I FOR EACH STATEMENT EXECUTE FUNCTION auth_audit_v4._guard()',t);
 EXECUTE format('ALTER TABLE auth_audit_v4.%I ENABLE ALWAYS TRIGGER auth_audit_write_guard',t);EXECUTE format('ALTER TABLE auth_audit_v4.%I ENABLE ALWAYS TRIGGER auth_audit_truncate_guard',t);
 END LOOP;END $$;
CREATE FUNCTION auth_audit_v4._assert(delivery boolean) RETURNS void LANGUAGE plpgsql AS $$ DECLARE m auth_audit_v4._meta;e bigint;r record;BEGIN
 PERFORM pg_advisory_xact_lock_shared(1229213011,3);LOCK TABLE auth_audit_v4._meta,auth_audit_v4.events,auth_audit_v4.streams,auth_audit_v4.delivery,auth_audit_v4._drafts,public.auth_state IN ACCESS SHARE MODE;
 SELECT * INTO STRICT m FROM auth_audit_v4._meta;IF current_user::regrole::oid<>m.owner_oid OR session_user::regrole::oid<>(CASE WHEN delivery THEN m.delivery_oid ELSE m.app_oid END) THEN RAISE EXCEPTION 'AUTH_AUDIT_AUTHORITY';END IF;
 FOR r IN SELECT * FROM pg_roles WHERE oid IN(m.owner_oid,m.app_oid,m.delivery_oid) LOOP IF r.rolsuper OR r.rolcreatedb OR r.rolcreaterole OR r.rolinherit OR r.rolreplication OR r.rolbypassrls OR r.rolcanlogin<>(r.oid<>m.owner_oid) OR EXISTS(SELECT 1 FROM pg_auth_members WHERE member=r.oid OR (roleid=r.oid AND r.oid<>m.owner_oid)) THEN RAISE EXCEPTION 'AUTH_AUDIT_AUTHORITY';END IF;END LOOP;
 IF (SELECT count(*) FROM pg_roles WHERE oid IN(m.owner_oid,m.app_oid,m.delivery_oid))<>3 OR (SELECT count(*) FROM pg_trigger WHERE tgrelid='public.auth_state'::regclass AND tgname IN('auth_audit_session_write_v4','auth_audit_session_truncate_v4') AND tgenabled='A')<>2 OR (SELECT count(*) FROM pg_event_trigger WHERE evtname IN('auth_audit_ddl_start_v4','auth_audit_ddl_end_v4','auth_audit_sql_drop_v4') AND evtenabled='A')<>3 THEN RAISE EXCEPTION 'AUTH_AUDIT_AUTHORITY';END IF;
 SELECT CASE WHEN is_called THEN last_value ELSE 0 END INTO e FROM auth_audit_v4._ddl_epoch;IF e<>m.epoch THEN RAISE EXCEPTION 'AUTH_AUDIT_SCHEMA_EPOCH';END IF;
END $$;
CREATE FUNCTION auth_audit_v4._pending_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ BEGIN IF EXISTS(SELECT 1 FROM auth_audit_v4._drafts WHERE pid=pg_backend_pid() AND tx=txid_current()) THEN RAISE EXCEPTION 'AUTH_AUDIT_UNCONSUMED_DRAFT';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER auth_audit_draft_consumed AFTER INSERT ON auth_audit_v4._drafts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION auth_audit_v4._pending_guard();
ALTER TABLE auth_audit_v4._drafts ENABLE ALWAYS TRIGGER auth_audit_draft_consumed;
CREATE FUNCTION auth_audit_v4.reserve_v4(scope text,tenant text,lookup text,action text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ DECLARE s auth_audit_v4.streams;d auth_audit_v4._drafts;BEGIN
 PERFORM auth_audit_v4._assert(false);IF scope IS NULL OR scope!~'^[a-f0-9]{64}$' OR tenant IS NULL OR tenant!~'^[A-Za-z0-9_-]{1,80}$' OR lookup IS NULL OR lookup!~'^[a-f0-9]{64}$' OR action IS NULL OR action NOT IN('AUTH_LOGIN','AUTH_LOGOUT','AUTH_SESSION_REPLACED','AUTH_SESSION_REVOKED','AUTH_SESSION_EXPIRED') THEN RAISE EXCEPTION 'AUTH_AUDIT_INPUT';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('auth-audit:'||scope||':'||tenant,0));
 INSERT INTO auth_audit_v4._ctx VALUES(pg_backend_pid(),txid_current());INSERT INTO auth_audit_v4.streams(scope,tenant) VALUES(scope,tenant) ON CONFLICT DO NOTHING;
 SELECT * INTO STRICT s FROM auth_audit_v4.streams x WHERE x.scope=reserve_v4.scope AND x.tenant=reserve_v4.tenant FOR UPDATE;
 IF action='AUTH_LOGIN' AND s.emitted-s.delivered>=10000 THEN RAISE EXCEPTION 'AUTH_AUDIT_BACKPRESSURE';END IF;
 INSERT INTO auth_audit_v4._drafts(pid,tx,id,scope,tenant,lookup_hash,action,position,occurred_ms,previous_hash) VALUES(pg_backend_pid(),txid_current(),gen_random_uuid(),scope,tenant,lookup,action,s.emitted+1,floor(extract(epoch from clock_timestamp())*1000)::bigint,s.emitted_hash) RETURNING * INTO d;
 DELETE FROM auth_audit_v4._ctx WHERE pid=pg_backend_pid();RETURN jsonb_build_object('scope',d.scope,'tenantId',d.tenant,'eventId',d.id,'position',d.position::text,'action',d.action,'occurredAtMs',d.occurred_ms::text,'previousHash',d.previous_hash);
END $$;
CREATE FUNCTION auth_audit_v4.stage_v4(wanted uuid,reference text,digest text,chain text,sealed jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ DECLARE d auth_audit_v4._drafts;expected text;BEGIN
 PERFORM auth_audit_v4._assert(false);SELECT * INTO STRICT d FROM auth_audit_v4._drafts WHERE pid=pg_backend_pid() AND tx=txid_current() AND id=wanted;
 IF reference IS NULL OR reference!~'^[a-f0-9]{64}$' OR digest IS NULL OR digest!~'^[a-f0-9]{64}$' OR chain IS NULL OR sealed IS NULL OR jsonb_typeof(sealed)<>'object' OR octet_length(sealed::text)>100000 OR d.sealed IS NOT NULL THEN RAISE EXCEPTION 'AUTH_AUDIT_INPUT';END IF;
 expected:=encode(sha256(convert_to(concat_ws(E'\n','IDMS_AUTH_AUDIT_V4_1',d.scope,d.tenant,d.position::text,d.id::text,d.action,d.occurred_ms::text,digest,d.previous_hash,reference),'UTF8')),'hex');IF chain<>expected THEN RAISE EXCEPTION 'AUTH_AUDIT_CHAIN';END IF;
 INSERT INTO auth_audit_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE auth_audit_v4._drafts SET session_ref=reference,digest=stage_v4.digest,chain_hash=chain,sealed=stage_v4.sealed WHERE pid=pg_backend_pid();DELETE FROM auth_audit_v4._ctx WHERE pid=pg_backend_pid();
END $$;
CREATE FUNCTION auth_audit_v4._session_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ DECLARE d auth_audit_v4._drafts;v_scope text;v_lookup text;BEGIN
 IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'AUTH_SESSION_AUDIT_REQUIRED';END IF;
 IF TG_OP='UPDATE' THEN IF ROW(OLD.scope_hash,OLD.kind,OLD.lookup_hash,OLD.expires_at) IS DISTINCT FROM ROW(NEW.scope_hash,NEW.kind,NEW.lookup_hash,NEW.expires_at) OR NEW.revision<>OLD.revision+1 THEN RAISE EXCEPTION 'AUTH_SESSION_IDENTITY_IMMUTABLE';END IF;RETURN NEW;END IF;
 IF TG_OP='INSERT' THEN IF NEW.kind<>'SESSION' THEN RETURN NEW;END IF;v_scope:=NEW.scope_hash;v_lookup:=NEW.lookup_hash;ELSE IF OLD.kind<>'SESSION' THEN RETURN OLD;END IF;v_scope:=OLD.scope_hash;v_lookup:=OLD.lookup_hash;END IF;
 PERFORM auth_audit_v4._assert(false);SELECT * INTO d FROM auth_audit_v4._drafts x WHERE x.pid=pg_backend_pid() AND x.tx=txid_current() AND x.scope=v_scope AND x.lookup_hash=v_lookup;
 IF NOT FOUND OR d.sealed IS NULL OR (TG_OP='INSERT' AND d.action<>'AUTH_LOGIN') OR (TG_OP='DELETE' AND (d.action='AUTH_LOGIN' OR (d.action='AUTH_SESSION_EXPIRED' AND OLD.expires_at>clock_timestamp()))) THEN RAISE EXCEPTION 'AUTH_SESSION_AUDIT_REQUIRED';END IF;
 INSERT INTO auth_audit_v4._ctx VALUES(pg_backend_pid(),txid_current());
 INSERT INTO auth_audit_v4.events(id,scope,tenant,position,lookup_hash,action,occurred_ms,previous_hash,session_ref,digest,chain_hash,sealed) VALUES(d.id,d.scope,d.tenant,d.position,d.lookup_hash,d.action,d.occurred_ms,d.previous_hash,d.session_ref,d.digest,d.chain_hash,d.sealed);
 INSERT INTO auth_audit_v4.delivery(id,status) VALUES(d.id,'PENDING');UPDATE auth_audit_v4.streams SET emitted=d.position,emitted_hash=d.chain_hash WHERE streams.scope=d.scope AND streams.tenant=d.tenant AND emitted=d.position-1 AND emitted_hash=d.previous_hash;IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_AUDIT_STREAM_CONFLICT';END IF;
 DELETE FROM auth_audit_v4._drafts WHERE pid=pg_backend_pid();DELETE FROM auth_audit_v4._ctx WHERE pid=pg_backend_pid();IF TG_OP='DELETE' THEN RETURN OLD;ELSE RETURN NEW;END IF;
END $$;
CREATE TRIGGER auth_audit_session_write_v4 BEFORE INSERT OR UPDATE OR DELETE ON public.auth_state FOR EACH ROW EXECUTE FUNCTION auth_audit_v4._session_guard();
CREATE TRIGGER auth_audit_session_truncate_v4 BEFORE TRUNCATE ON public.auth_state FOR EACH STATEMENT EXECUTE FUNCTION auth_audit_v4._session_guard();
ALTER TABLE public.auth_state ENABLE ALWAYS TRIGGER auth_audit_session_write_v4;ALTER TABLE public.auth_state ENABLE ALWAYS TRIGGER auth_audit_session_truncate_v4;
CREATE FUNCTION auth_audit_v4._public(e auth_audit_v4.events) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('header',jsonb_build_object('scope',e.scope,'tenantId',e.tenant,'eventId',e.id,'position',e.position::text,'action',e.action,'occurredAtMs',e.occurred_ms::text,'previousHash',e.previous_hash,'sessionRef',e.session_ref,'digest',e.digest,'chainHash',e.chain_hash),'sealed',e.sealed) $$;
CREATE FUNCTION auth_audit_v4.event_v4(scope text,wanted uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ DECLARE e auth_audit_v4.events;BEGIN PERFORM auth_audit_v4._assert(false);SELECT * INTO e FROM auth_audit_v4.events x WHERE x.scope=event_v4.scope AND id=wanted;IF NOT FOUND THEN RETURN NULL;END IF;RETURN auth_audit_v4._public(e);END $$;
CREATE FUNCTION auth_audit_v4.login_v4(scope text,lookup text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ DECLARE e auth_audit_v4.events;BEGIN PERFORM auth_audit_v4._assert(false);SELECT * INTO e FROM auth_audit_v4.events x WHERE x.scope=login_v4.scope AND lookup_hash=lookup AND action='AUTH_LOGIN';IF NOT FOUND THEN RETURN NULL;END IF;RETURN auth_audit_v4._public(e);END $$;
CREATE FUNCTION auth_audit_v4.claim_v4(scope text,tenant text,owner uuid,token uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ DECLARE d auth_audit_v4.delivery;e auth_audit_v4.events;BEGIN
 PERFORM auth_audit_v4._assert(true);IF scope IS NULL OR scope!~'^[a-f0-9]{64}$' OR tenant IS NULL OR tenant!~'^[A-Za-z0-9_-]{1,80}$' OR owner IS NULL OR token IS NULL THEN RAISE EXCEPTION 'AUTH_AUDIT_INPUT';END IF;
 SELECT q.* INTO d FROM auth_audit_v4.delivery q JOIN auth_audit_v4.events ev ON ev.id=q.id JOIN auth_audit_v4.streams s ON s.scope=ev.scope AND s.tenant=ev.tenant WHERE ev.scope=claim_v4.scope AND ev.tenant=claim_v4.tenant AND ev.position=s.delivered+1 AND q.status<>'DELIVERED' AND q.available_at<=clock_timestamp() AND (q.status<>'RUNNING' OR q.lease_until<=clock_timestamp()) ORDER BY ev.position FOR UPDATE OF q SKIP LOCKED LIMIT 1;
 IF NOT FOUND THEN RETURN NULL;END IF;INSERT INTO auth_audit_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE auth_audit_v4.delivery SET status='RUNNING',owner=claim_v4.owner,token=claim_v4.token,fence=fence+1,lease_until=clock_timestamp()+interval '30 seconds',attempts=attempts+1,error_code=NULL WHERE id=d.id RETURNING * INTO d;DELETE FROM auth_audit_v4._ctx WHERE pid=pg_backend_pid();
 SELECT * INTO STRICT e FROM auth_audit_v4.events WHERE id=d.id;RETURN auth_audit_v4._public(e)||jsonb_build_object('owner',d.owner,'token',d.token,'fence',d.fence::text,'attempts',d.attempts,'leaseUntil',d.lease_until);
END $$;
CREATE FUNCTION auth_audit_v4._lease(scope text,wanted uuid,owner uuid,token uuid,fence bigint) RETURNS auth_audit_v4.delivery LANGUAGE plpgsql AS $$ DECLARE d auth_audit_v4.delivery;BEGIN SELECT q.* INTO d FROM auth_audit_v4.delivery q JOIN auth_audit_v4.events e ON e.id=q.id WHERE q.id=wanted AND e.scope=_lease.scope FOR UPDATE OF q;IF NOT FOUND OR d.status<>'RUNNING' OR d.owner IS DISTINCT FROM owner OR d.token IS DISTINCT FROM token OR d.fence IS DISTINCT FROM fence OR d.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'AUTH_AUDIT_LEASE_LOST';END IF;RETURN d;END $$;
CREATE FUNCTION auth_audit_v4.renew_v4(scope text,wanted uuid,owner uuid,token uuid,fence bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ BEGIN PERFORM auth_audit_v4._assert(true);PERFORM auth_audit_v4._lease(scope,wanted,owner,token,fence);INSERT INTO auth_audit_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE auth_audit_v4.delivery SET lease_until=clock_timestamp()+interval '30 seconds' WHERE id=wanted;DELETE FROM auth_audit_v4._ctx WHERE pid=pg_backend_pid();RETURN true;END $$;
CREATE FUNCTION auth_audit_v4.defer_v4(scope text,wanted uuid,owner uuid,token uuid,fence bigint,code text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ DECLARE d auth_audit_v4.delivery;BEGIN PERFORM auth_audit_v4._assert(true);d:=auth_audit_v4._lease(scope,wanted,owner,token,fence);IF code IS NULL OR code!~'^[A-Z0-9_]{1,80}$' THEN RAISE EXCEPTION 'AUTH_AUDIT_INPUT';END IF;INSERT INTO auth_audit_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE auth_audit_v4.delivery SET status='RETRY',available_at=clock_timestamp()+make_interval(secs=>LEAST(300,attempts)),owner=NULL,token=NULL,lease_until=NULL,error_code=code WHERE id=wanted;DELETE FROM auth_audit_v4._ctx WHERE pid=pg_backend_pid();END $$;
CREATE FUNCTION auth_audit_v4.ack_v4(scope text,wanted uuid,owner uuid,token uuid,fence bigint,receipt jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ DECLARE d auth_audit_v4.delivery;e auth_audit_v4.events;BEGIN
 PERFORM auth_audit_v4._assert(true);d:=auth_audit_v4._lease(scope,wanted,owner,token,fence);SELECT * INTO STRICT e FROM auth_audit_v4.events WHERE id=wanted;
 IF receipt IS NULL OR jsonb_typeof(receipt)<>'object' OR octet_length(receipt::text)>8192 OR receipt->'completion'->>'sourceEventId' IS DISTINCT FROM e.id::text OR receipt->'completion'->>'sourcePosition' IS DISTINCT FROM e.position::text OR receipt->'completion'->>'tenantId' IS DISTINCT FROM e.tenant OR receipt->'completion'->>'sourceChainHash' IS DISTINCT FROM e.chain_hash THEN RAISE EXCEPTION 'AUTH_AUDIT_RECEIPT';END IF;
 INSERT INTO auth_audit_v4._ctx VALUES(pg_backend_pid(),txid_current());UPDATE auth_audit_v4.streams SET delivered=e.position WHERE streams.scope=e.scope AND streams.tenant=e.tenant AND delivered=e.position-1;IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_AUDIT_DELIVERY_SEQUENCE';END IF;
 UPDATE auth_audit_v4.delivery SET status='DELIVERED',receipt=ack_v4.receipt,owner=NULL,token=NULL,lease_until=NULL WHERE id=wanted;DELETE FROM auth_audit_v4._ctx WHERE pid=pg_backend_pid();
END $$;
CREATE FUNCTION auth_audit_v4.delivery_v4(scope text,wanted uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ DECLARE d auth_audit_v4.delivery;BEGIN PERFORM auth_audit_v4._assert(true);SELECT q.* INTO d FROM auth_audit_v4.delivery q JOIN auth_audit_v4.events e ON e.id=q.id WHERE e.scope=delivery_v4.scope AND e.id=wanted;IF NOT FOUND THEN RETURN NULL;END IF;RETURN jsonb_build_object('status',d.status,'fence',d.fence::text,'attempts',d.attempts,'errorCode',d.error_code,'receipt',d.receipt);END $$;
CREATE FUNCTION auth_audit_v4.verify_v4(delivery boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ DECLARE m auth_audit_v4._meta;BEGIN PERFORM auth_audit_v4._assert(delivery);SELECT * INTO STRICT m FROM auth_audit_v4._meta;RETURN jsonb_build_object('deployment',m.deployment,'databaseOid',(SELECT oid::text FROM pg_database WHERE datname=current_database()),'roleOid',session_user::regrole::oid::text,'keyCheck',m.key_check);END $$;
REVOKE ALL ON SCHEMA auth_audit_v4 FROM PUBLIC;REVOKE ALL ON ALL TABLES IN SCHEMA auth_audit_v4 FROM PUBLIC;REVOKE ALL ON ALL SEQUENCES IN SCHEMA auth_audit_v4 FROM PUBLIC;REVOKE ALL ON ALL FUNCTIONS IN SCHEMA auth_audit_v4 FROM PUBLIC;
GRANT USAGE ON SCHEMA auth_audit_v4 TO __APP__,__DELIVERY__;
GRANT EXECUTE ON FUNCTION auth_audit_v4.verify_v4(boolean) TO __APP__,__DELIVERY__;
GRANT EXECUTE ON FUNCTION auth_audit_v4.reserve_v4(text,text,text,text),auth_audit_v4.stage_v4(uuid,text,text,text,jsonb),auth_audit_v4.event_v4(text,uuid),auth_audit_v4.login_v4(text,text) TO __APP__;
GRANT EXECUTE ON FUNCTION auth_audit_v4.claim_v4(text,text,uuid,uuid),auth_audit_v4.renew_v4(text,uuid,uuid,uuid,bigint),auth_audit_v4.defer_v4(text,uuid,uuid,uuid,bigint,text),auth_audit_v4.ack_v4(text,uuid,uuid,uuid,bigint,jsonb),auth_audit_v4.delivery_v4(text,uuid) TO __DELIVERY__;
RESET ROLE;
CREATE FUNCTION auth_audit_v4._ddl_start() RETURNS event_trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ BEGIN PERFORM pg_advisory_xact_lock(1229213011,3);END $$;
CREATE FUNCTION auth_audit_v4._ddl_end() RETURNS event_trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ BEGIN IF EXISTS(SELECT 1 FROM pg_event_trigger_ddl_commands() WHERE schema_name='auth_audit_v4' OR (schema_name='public' AND command_tag IN('ALTER TABLE','CREATE TRIGGER','ALTER TRIGGER','DROP TRIGGER'))) THEN PERFORM nextval('auth_audit_v4._ddl_epoch');END IF;END $$;
CREATE FUNCTION auth_audit_v4._sql_drop() RETURNS event_trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,auth_audit_v4,pg_temp AS $$ BEGIN IF EXISTS(SELECT 1 FROM pg_event_trigger_dropped_objects() WHERE schema_name IN('auth_audit_v4','public')) THEN PERFORM nextval('auth_audit_v4._ddl_epoch');END IF;END $$;
ALTER FUNCTION auth_audit_v4._ddl_start() OWNER TO __OWNER__;ALTER FUNCTION auth_audit_v4._ddl_end() OWNER TO __OWNER__;ALTER FUNCTION auth_audit_v4._sql_drop() OWNER TO __OWNER__;
REVOKE ALL ON FUNCTION auth_audit_v4._ddl_start(),auth_audit_v4._ddl_end(),auth_audit_v4._sql_drop() FROM PUBLIC;
CREATE EVENT TRIGGER auth_audit_ddl_start_v4 ON ddl_command_start EXECUTE FUNCTION auth_audit_v4._ddl_start();CREATE EVENT TRIGGER auth_audit_ddl_end_v4 ON ddl_command_end EXECUTE FUNCTION auth_audit_v4._ddl_end();CREATE EVENT TRIGGER auth_audit_sql_drop_v4 ON sql_drop EXECUTE FUNCTION auth_audit_v4._sql_drop();
ALTER EVENT TRIGGER auth_audit_ddl_start_v4 ENABLE ALWAYS;ALTER EVENT TRIGGER auth_audit_ddl_end_v4 ENABLE ALWAYS;ALTER EVENT TRIGGER auth_audit_sql_drop_v4 ENABLE ALWAYS;
